sys_variable_value.value:
(function execute(inputs, outputs) {
    var onb_req = new GlideRecord('x_snc_cpa_onboar_0_onboard_req');
    onb_req.addEncodedQuery('number='+inputs.onb_req_num);
    onb_req.query();
    if(onb_req.next()) {
        var usr_rec = new GlideRecord('sys_user');
        if(usr_rec.get(onb_req.employee)) {
        //usr_rec.query();
        //if(usr_rec.next()) {
            var response = "";
            var cpa_profile = new GlideRecord('x_snc_cpa_onboar_0_cpa_profile');
            //cpa_profile.addEncodedQuery('employee.user_name='+inputs.user_id);
            //cpa_profile.query();
            if(cpa_profile.get(usr_rec.x_snc_nask_quali_0_cpa_profile)) {
            //if(cpa_profile.next()) {
                var userData = {
                    user_id: usr_rec.getUniqueValue(),
                    user_name: usr_rec.getValue('user_name'),
                    user_fullname: usr_rec.getValue('name'),
                    user_email: usr_rec.getValue('email'),
                    company: cpa_profile.getDisplayValue('company'),
                    department: cpa_profile.getDisplayValue('department'),
                    port: cpa_profile.getDisplayValue('port')
                    //is_locked_out: usr_rec.getDisplayValue('locked_out'),
                    //department: usr_rec.getDisplayValue('department'),
                    // roles: getUserRoles(usr_rec.getUniqueValue())
                }
                response = JSON.stringify(userData);
            }
        }
        else {
            response = "User not found! Unable to fetch user details."
        }
        outputs.user_data = response;
    }
})(inputs, outputs);

